ST.xhtml:
A00_设备状态显示及控制 ();

A20_机器人();
%MW1000:=0;

PLC_Cyinder_气缸动作();

CASE MODE_State OF
	EN_功能块状态.运行:
		A10_上下料伺服流程 ();
		Sample_point_sampling_上样点样();
		Collection_process_收集流程();
		Expand_process_展开流程();
		Photo_scraper_拍照刮板();
		Robotic_Process_机器人流程();
		Develop_TankDrain();

END_CASE

TON_3(IN:=复位,PT:=T#5S );
IF NOT 急停 OR TON_3.Q THEN
	A30_急停();
END_IF
IF MODE_State<>1 THEN
	伺服上料_Setp:=0;
	伺服下料_Setp:=0;
END_IF

//初始化
IF MODE_State =4 OR  初始化  THEN

		玻璃上料轴1ZDATE.fAbsTarget :=0;
		玻璃上料轴1ZDATE.xMoveAbs:=TRUE;
		玻璃上料轴1ZDATE.xJogPos :=FALSE;
		升降上料伺服允许取料 :=FALSE ;
		升降上料伺服下降完成 :=FALSE ;
		伺服上料_Setp:=0;
		伺服上料_Setp:=0;
		升降下料伺服允许放料  :=FALSE ;
		玻璃上料轴2ZDATE.xJogNeg :=FALSE;
		玻璃上料轴2ZDATE.xJogPos :=FALSE;

END_IF



//上料流程
IF MODE_State =1 THEN     //自动模式下
	IF 玻璃上料轴1ZDATE.bHomed AND 玻璃升降接近开关1 AND 上料进料传感器 AND 伺服上料_Setp=0 AND NOT Alarm.0 AND 升降上料完成 THEN
		伺服上料_Setp :=1;
	END_IF

    CASE 伺服上料_Setp OF
    	1 :
			IF NOT 玻璃升降光电开关1 AND 玻璃上料轴1ZDATE.fActPos<514  THEN
				Z1JOG_pos :=TRUE;
				ELSE
				Z1JOG_pos :=FALSE;
				伺服上料_Setp:=10;
			END_IF

	   10:
		   IF 玻璃升降光电开关1 THEN
		   	升降上料伺服允许取料 :=TRUE;
			伺服上料_Setp:=20;
		   END_IF

	   20:
		   IF 升降上料机器人已吸住物料 THEN
		   	玻璃上料轴1ZDATE.fRelTarget :=-5.0;
			玻璃上料轴1ZDATE.xMoveRel :=TRUE;
			伺服上料_Setp:=30;
		   END_IF
	   30:
		   IF 玻璃上料轴1ZDATE .bReMoveDone  THEN
		   	升降上料伺服下降完成 :=TRUE ;
			玻璃上料轴1ZDATE.xMoveRel :=FALSE;
			伺服上料_Setp:=40;
		   END_IF
	   40:
		   IF 升降上料机器人取料完成  THEN
		   	升降上料伺服下降完成 :=FALSE ;
			升降上料伺服允许取料 :=FALSE ;
			伺服上料_Setp:=1;
		   END_IF 
    END_CASE

	IF 玻璃上料轴1ZDATE.fActPos>=514 AND  玻璃升降光电开关1 THEN
		Alarm.0:=TRUE;                                             //上料机构无物料
		升降上料完成:=FALSE;
		玻璃上料轴1ZDATE.fAbsTarget :=0;
		玻璃上料轴1ZDATE.xMoveAbs:=TRUE;
		Z1JOG_pos :=FALSE;
		升降上料伺服允许取料 :=FALSE ;
		升降上料伺服下降完成 :=FALSE ;
		伺服上料_Setp:=0;
	END_IF
	IF 玻璃上料轴1ZDATE .bAbMoveDone  THEN
		玻璃上料轴1ZDATE.xMoveAbs:=FALSE;
		升降上料机器人放料完成:=FALSE;
    END_IF


END_IF
//下料流程
IF MODE_State =1 THEN     //自动模式下
	IF 玻璃上料轴2ZDATE.bHomed  AND 下料出料传感器 AND 伺服下料_Setp=0 AND NOT Alarm.1 AND 升降下料完成 THEN
		伺服下料_Setp :=1;
	END_IF

    CASE 伺服下料_Setp  OF
    	1 :
			IF NOT 玻璃升降光电开关2 AND 玻璃上料轴2ZDATE.fActPos<510  THEN
				Z2JOG_POS :=TRUE;
				ELSE
				Z2JOG_POS :=FALSE;
				伺服下料_Setp:=10;
			END_IF

	   10:
		   IF 玻璃升降光电开关2 THEN
			   Z2JOG_NEG :=TRUE;
			   伺服下料_Setp:=15;
		   END_IF
	   15:
		   IF NOT 玻璃升降光电开关2  THEN
				升降下料伺服允许放料  :=TRUE;
				Z2JOG_NEG :=FALSE;
				伺服下料_Setp:=20;
		   END_IF


	   20:
		   IF 升降下料机器人放废料完成 AND 玻璃升降光电开关2 AND 玻璃升降接近开关2 THEN
		   	Z2JOG_NEG :=TRUE;
			升降下料伺服允许放料  :=FALSE ;
			伺服下料_Setp:=30;
		   END_IF

	   30:
		   IF NOT 玻璃升降光电开关2 THEN
		   	Z2JOG_NEG :=FALSE;
			伺服下料_Setp:=10;
		   END_IF

    END_CASE

	IF 玻璃上料轴2ZDATE.fActPos<=0 AND 玻璃升降光电开关1 THEN
		Alarm.1:=TRUE;                                           //下料机构已满料
		升降下料完成:=FALSE;
		伺服下料_Setp:=0;
		升降下料伺服允许放料  :=FALSE ;
		Z2JOG_NEG :=FALSE;
		Z2JOG_POS :=FALSE;
		玻璃上料轴2ZDATE.fAbsTarget :=0;
		玻璃上料轴2ZDATE.xMoveAbs:=TRUE;
		伺服下料_Setp:=0;
	END_IF
	IF 玻璃上料轴2ZDATE .bAbMoveDone  THEN
		玻璃上料轴2ZDATE.xMoveAbs:=FALSE;
		升降下料伺服允许放料  :=FALSE ;
    END_IF
END_IF

//PLC模式切换
PLC_Mode_0(
    bWarning_alarm := cyinderAlarm<>0 OR Alarm<>0 OR 上样料架报警, 

	xStart:= 启动 , 
	xStop:=NOT  停止 , 
	xReset:=复位  , 
	xAutoMode:=手自动  , 
	xFault:=伺服报警 OR ECAT掉站报警 OR 伺服未回原点报警, 
	xEmergency:= 急停 , 
	bRed=>三色灯红  , 
	bYellow=> 三色灯黄, 
	bGreen=> 三色灯绿, 
	bBuzzer=> 蜂鸣器 , 
	iState=>MODE_STATE  , 
	bAuto=>ManualAuto  );

	//伺服报错
IF   玻璃上料轴1ZDATE.bError OR 玻璃上料轴2ZDATE.bError OR 打样瓶上料轴3YDATE.bError OR 点样轴6XDATE.bError OR 点样轴7YDATE.bError OR 拍照轴8YDATE.bError OR 刮板轴9XDATE.bError OR 刮板轴10ZDATE.bError OR 地轨轴11YDATE.bError OR 上样轴4X轴DATE.bError OR 上样轴5Z轴DATE.bError THEN
	伺服报警:=TRUE;
END_IF
   //伺服报错复位
IF 复位 THEN
	伺服报警:=FALSE;
	伺服未回原点报警:=FALSE;
	Alarm:=0;
	cyinderAlarm:=0;
	上样料架报警:=FALSE;
END_IF


IF NOT 玻璃上料轴1ZDATE.bHomed OR NOT 玻璃上料轴2ZDATE.bHomed OR NOT 打样瓶上料轴3YDATE.bHomed OR NOT 点样轴6XDATE.bHomed OR NOT 点样轴7YDATE.bHomed OR NOT 拍照轴8YDATE.bHomed OR NOT 刮板轴9XDATE.bHomed OR NOT 刮板轴10ZDATE.bHomed  OR NOT 地轨轴11YDATE.bHomed OR NOT 上样轴4X轴DATE.bHomed OR NOT 上样轴5Z轴DATE.bHomed THEN
	伺服未回原点报警:=TRUE ;
END_IF

伺服上料_Setp:=0;
伺服下料_Setp:=0;
